const state={user:null,conversations:[],selected:null,users:[],filter:'all',tagFilter:'',priorityFilter:'',assignmentFilter:'',timer:null,automations:[],selectedAutomation:null,knowledgeSources:[],selectedSource:null,whatsappAccount:null,onboarding:null,contacts:[],selectedContact:null,contactSearchTimer:null,lastHumanUnread:null,lastFailedOutbound:null,pendingMessage:null,quickReplies:[],tags:[],conversationTags:[],conversationEvents:[]};
const $=id=>document.getElementById(id);
function apiErrorDetail(detail){if(Array.isArray(detail))return detail.map(item=>item.msg||'Campo inválido.').join(' ');return typeof detail==='string'?detail:null}
function csrfToken(){return document.cookie.split('; ').find(item=>item.startsWith('neria_csrf='))?.split('=')[1]||''}
async function api(path,options={}){const hadSession=Boolean(state.user),headers={'Content-Type':'application/json',...(options.headers||{})};if(!['GET','HEAD','OPTIONS'].includes(options.method||'GET'))headers['X-CSRF-Token']=csrfToken();let response;try{response=await fetch(`/api/v1${path}`,{...options,headers})}catch{throw new Error('Não foi possível conectar à Neria. Verifique sua internet e tente novamente.')}if(response.status===401&&hadSession){showLoggedOut();throw new Error('Sua sessão expirou. Entre novamente.')}if(!response.ok){let detail=null;try{detail=apiErrorDetail((await response.json()).detail)}catch{}const defaults={401:'E-mail ou senha inválidos.',403:'Você não tem permissão para realizar esta ação.',402:'Sua assinatura não está ativa. Entre em contato com o suporte.',409:'Esta operação não pode ser concluída no estado atual.',422:'Revise os campos informados.',429:'Muitas tentativas. Aguarde um pouco e tente novamente.',500:'Ocorreu uma falha interna.',502:'Um serviço externo não respondeu.',503:'A Neria está temporariamente indisponível.'};let message=detail||defaults[response.status]||'Não foi possível concluir a operação.';if(response.status>=500){const requestId=response.headers.get('X-Request-ID');message+=` Tente novamente em instantes.${requestId?` Código de suporte: ${requestId}.`:''}`}throw new Error(message)}return response.status===204?null:response.json()}
function initials(name=''){return name.split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()||'?'}
function escapeHtml(value=''){const node=document.createElement('div');node.textContent=value;return node.innerHTML}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800)}
function showLoggedOut(){state.user=null;clearInterval(state.timer);$('app-view').classList.add('hidden');$('login-view').classList.remove('hidden');showAuthPanel('login')}
async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{showLoggedOut()}}
async function login(event){event.preventDefault();const button=event.submitter;button.disabled=true;$('login-error').textContent='';try{await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});await bootstrap()}catch(error){$('login-error').textContent=error.message}finally{button.disabled=false}}
function organizationSlug(name){const base=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,65)||'empresa';const suffix=crypto.getRandomValues(new Uint32Array(1))[0].toString(36).slice(0,6);return `${base}-${suffix}`}
async function registerOrganization(event){event.preventDefault();const button=event.submitter,message=$('registration-error');button.disabled=true;message.textContent='';const company=$('registration-company').value.trim();try{await api('/auth/register',{method:'POST',body:JSON.stringify({organization_name:company,organization_slug:organizationSlug(company),admin_name:$('registration-name').value.trim(),admin_email:$('registration-email').value.trim(),password:$('registration-password').value})});await bootstrap()}catch(error){message.textContent=error.message}finally{button.disabled=false}}
function showAuthPanel(panel){$('login-copy').classList.toggle('hidden',panel!=='login');$('login-form').classList.toggle('hidden',panel!=='login');$('registration-form').classList.toggle('hidden',panel!=='registration');$('forgot-form').classList.toggle('hidden',panel!=='forgot');$('reset-form').classList.toggle('hidden',panel!=='reset');if(panel==='registration')$('registration-company').focus();if(panel==='forgot'){$('forgot-email').value=$('email').value;$('forgot-email').focus()}if(panel==='login')$('email').focus()}
async function requestPasswordReset(event){event.preventDefault();const message=$('forgot-message');message.textContent='';try{const result=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email:$('forgot-email').value.trim()})});message.textContent=result.message}catch(error){message.textContent=error.message}}
async function resetPassword(event){event.preventDefault();const password=$('reset-password').value,confirmation=$('reset-password-confirmation').value,message=$('reset-message');message.textContent='';if(password!==confirmation){message.textContent='As senhas não coincidem.';return}const token=new URLSearchParams(window.location.search).get('reset_token');if(!token){message.textContent='Link de recuperação inválido.';return}try{const result=await api('/auth/reset-password',{method:'POST',body:JSON.stringify({token,password})});window.history.replaceState({},'',window.location.pathname);$('reset-form').reset();showAuthPanel('login');$('login-error').textContent=result.message}catch(error){message.textContent=error.message}}
async function bootstrap({silent=false}={}){try{state.user=await api('/auth/me');state.users=await api('/users');$('user-name').textContent=state.user.name;$('user-role').textContent=state.user.role==='admin'?'Administrador':'Atendente';$('user-avatar').textContent=initials(state.user.name);['nav-onboarding','nav-automations','nav-knowledge','nav-ai','nav-whatsapp','nav-settings'].forEach(id=>$(id).classList.toggle('hidden',state.user.role!=='admin'));$('login-view').classList.add('hidden');$('app-view').classList.remove('hidden');renderAssignees();await Promise.all([loadTags(),loadQuickReplies()]);await loadInbox();if(state.user.role==='admin')await loadOnboarding(true);state.timer=setInterval(()=>loadInbox(false),8000)}catch(error){showLoggedOut();if(!silent)$('login-error').textContent=error.message}}
async function loadInbox(showErrors=true){try{const params=new URLSearchParams();if(state.tagFilter)params.set('tag_id',state.tagFilter);if(state.priorityFilter)params.set('priority',state.priorityFilter);if(state.assignmentFilter)params.set('assignment',state.assignmentFilter);const query=params.size?`?${params}`:'';state.conversations=await api(`/conversations/inbox${query}`);renderConversations();if(state.selected){const fresh=state.conversations.find(item=>item.id===state.selected.id);if(fresh){state.selected=fresh;renderHeader()}else{clearConversationSelection()}}await loadNotificationSummary(true)}catch(error){if(showErrors)toast(error.message)}}
function visibleConversations(){const query=$('search').value.trim().toLowerCase();return state.conversations.filter(item=>(state.filter==='all'||item.mode===state.filter)&&(!query||item.contact_name.toLowerCase().includes(query)||item.contact_phone.includes(query)))}
function renderConversations(){const items=visibleConversations();$('conversation-list').innerHTML=items.length?items.map(item=>`<button class="conversation-item ${state.selected?.id===item.id?'active':''}" data-id="${item.id}"><div class="avatar">${initials(item.contact_name)}</div><div class="conversation-main"><div class="conversation-top"><strong><i class="priority-dot ${item.priority}"></i>${escapeHtml(item.contact_name)}</strong><time>${formatListTime(item.last_message_at)}</time></div><div class="preview">${item.last_message_direction==='outbound'?'Você: ':''}${escapeHtml(item.last_message_body||'Nova conversa')}</div></div><div class="conversation-indicators"><span class="mode-badge ${item.mode}">${item.mode==='human'?'Humano':'Bot'}</span>${item.sla_status?`<span class="sla-badge ${item.sla_status}">${slaLabel(item)}</span>`:''}${item.unread_count?`<b class="unread-badge">${item.unread_count>99?'99+':item.unread_count}</b>`:''}</div></button>`).join(''):'<div class="list-empty">Nenhuma conversa encontrada.</div>';$('conversation-list').querySelectorAll('[data-id]').forEach(button=>button.onclick=()=>selectConversation(button.dataset.id))}
function slaLabel(item){if(item.sla_status==='overdue')return `Atrasado ${Math.max(0,item.waiting_minutes)} min`;const remaining=Math.max(0,Math.ceil((new Date(item.sla_due_at)-Date.now())/60000));return item.sla_status==='warning'?`Restam ${remaining} min`:`SLA ${remaining} min`}
function formatListTime(value){if(!value)return '';const date=new Date(value),now=new Date();return date.toDateString()===now.toDateString()?date.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}
async function displayConversation(conversation,{markRead=true}={}){state.selected=conversation;if(markRead){try{await api(`/conversations/${conversation.id}/mark-read`,{method:'POST'});state.selected.unread_count=0}catch(error){toast(error.message)}}$('empty-chat').classList.add('hidden');$('active-chat').classList.remove('hidden');$('app-view').classList.add('chat-open');renderConversations();renderHeader();await Promise.all([loadMessages(),loadConversationTags(),loadConversationEvents(),loadNotificationSummary(false)])}
async function selectConversation(id){const conversation=state.conversations.find(item=>item.id===id);if(!conversation)return;await displayConversation(conversation)}
function clearConversationSelection(){state.selected=null;state.conversationTags=[];state.conversationEvents=[];$('active-chat').classList.add('hidden');$('empty-chat').classList.remove('hidden');$('app-view').classList.remove('chat-open');$('conversation-timeline').classList.add('hidden')}
async function loadNotificationSummary(notify=true){try{const summary=await api('/notifications/summary'),attention=summary.total_unread+summary.failed_outbound,badge=$('notification-badge');badge.textContent=attention>99?'99+':attention;badge.classList.toggle('hidden',attention===0);if(notify&&state.lastHumanUnread!==null&&summary.human_unread>state.lastHumanUnread)toast('Nova mensagem aguardando atendimento humano.');if(notify&&state.lastFailedOutbound!==null&&summary.failed_outbound>state.lastFailedOutbound)toast('Uma mensagem não foi enviada. Abra a conversa para tentar novamente.');state.lastHumanUnread=summary.human_unread;state.lastFailedOutbound=summary.failed_outbound}catch(error){if(notify)toast(error.message)}}
function renderHeader(){const item=state.selected;if(!item)return;$('contact-name').textContent=item.contact_name;$('contact-phone').textContent=item.contact_phone;$('contact-avatar').textContent=initials(item.contact_name);$('assignee').value=item.assigned_user_id||'';$('conversation-priority').value=item.priority;$('toggle-mode').textContent=item.mode==='bot'?'Assumir atendimento':'Devolver ao bot';$('close-conversation').disabled=item.status==='closed';const expired=!item.last_customer_message_at||Date.now()-new Date(item.last_customer_message_at).getTime()>86400000;$('window-warning').classList.toggle('hidden',!expired);$('composer').classList.toggle('hidden',item.status==='closed')}
function renderAssignees(){$('assignee').innerHTML='<option value="">Sem responsável</option>'+state.users.filter(user=>user.is_active).map(user=>`<option value="${user.id}">${escapeHtml(user.name)}</option>`).join('')}
async function loadMessages(){try{const messages=await api(`/conversations/${state.selected.id}/messages?limit=100`);$('messages').innerHTML=messages.map(message=>`<div class="message-row ${message.direction}"><div class="bubble">${escapeHtml(message.body||mediaLabel(message))}<div class="bubble-meta"><span>${new Date(message.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span>${message.direction==='outbound'?`<span>${statusLabel(message.status)}</span>`:''}</div>${message.status==='failed'?`<div class="delivery-failure" title="${escapeHtml(message.delivery_error||'Falha no envio')}"><span>Mensagem não enviada${message.delivery_attempts?` após ${message.delivery_attempts} tentativa(s)`:''}.</span><button type="button" data-retry-message="${message.id}">Tentar novamente</button></div>`:''}${message.ai_run_id?`<div class="ai-feedback" data-ai-feedback="${message.ai_run_id}"><span>Resposta da IA</span><button type="button" data-helpful="${message.ai_run_id}" title="Resposta correta">✓ Útil</button><button type="button" data-correct="${message.ai_run_id}" title="Corrigir resposta">✎ Corrigir</button><div class="correction-form hidden"><textarea rows="3" minlength="10" maxlength="5000" placeholder="Digite a resposta correta para ensinar a Neria."></textarea><div><button type="button" data-cancel-correction>Cancelar</button><button type="button" data-submit-correction="${message.ai_run_id}">Enviar correção</button></div></div></div>${message.ai_source_titles?.length?`<div class="ai-sources" title="Fontes utilizadas pela IA">Fonte${message.ai_source_titles.length===1?'':'s'}: ${message.ai_source_titles.map(escapeHtml).join(' · ')}</div>`:''}`:''}</div></div>`).join('');bindAIFeedbackActions();$('messages').querySelectorAll('[data-retry-message]').forEach(button=>button.onclick=()=>retryMessage(button));$('messages').scrollTop=$('messages').scrollHeight}catch(error){toast(error.message)}}
async function retryMessage(button){button.disabled=true;try{await api(`/conversations/${state.selected.id}/messages/${button.dataset.retryMessage}/retry`,{method:'POST'});await loadMessages();toast('Reenvio colocado na fila.')}catch(error){toast(error.message);button.disabled=false}}
function bindAIFeedbackActions(){$('messages').querySelectorAll('[data-helpful]').forEach(button=>button.onclick=()=>submitAIFeedback(button.dataset.helpful,'helpful'));$('messages').querySelectorAll('[data-correct]').forEach(button=>button.onclick=()=>button.closest('.ai-feedback').querySelector('.correction-form').classList.remove('hidden'));$('messages').querySelectorAll('[data-cancel-correction]').forEach(button=>button.onclick=()=>button.closest('.correction-form').classList.add('hidden'));$('messages').querySelectorAll('[data-submit-correction]').forEach(button=>button.onclick=()=>{const form=button.closest('.correction-form'),correction=form.querySelector('textarea').value.trim();if(correction.length<10){toast('Informe uma resposta correta com pelo menos 10 caracteres.');return}submitAIFeedback(button.dataset.submitCorrection,'unhelpful',correction)})}
async function submitAIFeedback(runId,rating,correction=null){try{await api(`/ai/runs/${runId}/feedback`,{method:'POST',body:JSON.stringify({rating,correction})});const panel=document.querySelector(`[data-ai-feedback="${runId}"]`);if(panel)panel.innerHTML=`<span class="feedback-saved">✓ ${rating==='helpful'?'Resposta avaliada':'Correção enviada para revisão'}</span>`;toast(rating==='helpful'?'Avaliação registrada.':'Correção enviada ao administrador.')}catch(error){toast(error.message)}}
function mediaLabel(message){return {image:'🖼 Imagem',audio:'🎵 Áudio',document:'📄 Documento',interactive:'Menu interativo',template:'Template'}[message.message_type]||'Mensagem'}
function statusLabel(status){return {queued:'○',sent:'✓',delivered:'✓✓',read:'✓✓',failed:'!' }[status]||''}
async function patchConversation(changes){try{const updated=await api(`/conversations/${state.selected.id}`,{method:'PATCH',body:JSON.stringify(changes)});if(updated.status==='closed'){clearConversationSelection();await loadInbox();toast('Atendimento encerrado.');return}state.selected=updated;await Promise.all([loadInbox(),loadConversationEvents()]);renderHeader()}catch(error){toast(error.message)}}
async function loadConversationEvents(){if(!state.selected)return;try{state.conversationEvents=await api(`/conversations/${state.selected.id}/events`);renderConversationEvents()}catch(error){toast(error.message)}}
function eventValue(field,value){if(value===null||value==='None')return 'não definido';if(field==='assigned_user_id')return state.users.find(user=>user.id===value)?.name||'usuário removido';const labels={low:'baixa',normal:'normal',high:'alta',urgent:'urgente',bot:'bot',human:'humano',open:'aberta',closed:'encerrada'};return labels[value]||value}
function renderConversationEvents(){const labels={'assigned_user_id.changed':'Responsável alterado','priority.changed':'Prioridade alterada','mode.changed':'Modo de atendimento alterado','status.changed':'Situação alterada'};$('timeline-list').innerHTML=state.conversationEvents.length?state.conversationEvents.map(item=>{const note=item.event_type==='note.created',field=item.event_type.replace('.changed',''),detail=note?escapeHtml(item.content):`De ${escapeHtml(eventValue(field,item.event_data?.from))} para ${escapeHtml(eventValue(field,item.event_data?.to))}`;return `<article class="timeline-item ${note?'note':''}"><strong>${note?'Nota interna':labels[item.event_type]||'Atualização'}</strong><small>${escapeHtml(item.actor_name||'Sistema')} · ${new Date(item.created_at).toLocaleString('pt-BR')}</small><p>${detail}</p></article>`}).join(''):'<div class="list-empty">Nenhuma movimentação registrada.</div>'}
async function createConversationNote(event){event.preventDefault();const content=$('note-content').value.trim();if(!content)return;try{await api(`/conversations/${state.selected.id}/notes`,{method:'POST',body:JSON.stringify({content})});$('note-form').reset();await loadConversationEvents();toast('Nota interna adicionada.')}catch(error){toast(error.message)}}
async function loadTags(){try{state.tags=await api('/tags');renderTagControls();if(state.user?.role==='admin')renderTagsAdmin()}catch(error){toast(error.message)}}
function renderTagControls(){$('tag-filter').innerHTML='<option value="">Todas as etiquetas</option>'+state.tags.map(tag=>`<option value="${tag.id}">${escapeHtml(tag.name)}</option>`).join('');$('tag-filter').value=state.tagFilter;const assigned=new Set(state.conversationTags.map(tag=>tag.id));$('conversation-tag-picker').innerHTML='<option value="">+ Etiqueta</option>'+state.tags.filter(tag=>!assigned.has(tag.id)).map(tag=>`<option value="${tag.id}">${escapeHtml(tag.name)}</option>`).join('');$('conversation-tags-list').innerHTML=state.conversationTags.map(tag=>`<button type="button" class="tag-chip" style="--tag-color:${tag.color}" data-remove-tag="${tag.id}" title="Remover etiqueta">${escapeHtml(tag.name)} ×</button>`).join('');$('conversation-tags-list').querySelectorAll('[data-remove-tag]').forEach(button=>button.onclick=()=>removeConversationTag(button.dataset.removeTag))}
async function loadConversationTags(){if(!state.selected)return;try{state.conversationTags=await api(`/conversations/${state.selected.id}/tags`);renderTagControls()}catch(error){toast(error.message)}}
async function assignConversationTag(tagId){if(!tagId||!state.selected)return;try{await api(`/conversations/${state.selected.id}/tags/${tagId}`,{method:'POST'});await loadConversationTags()}catch(error){toast(error.message)}finally{$('conversation-tag-picker').value=''}}
async function removeConversationTag(tagId){try{await api(`/conversations/${state.selected.id}/tags/${tagId}`,{method:'DELETE'});await loadConversationTags();if(state.tagFilter===tagId)await loadInbox()}catch(error){toast(error.message)}}
function renderTagsAdmin(){$('tags-admin-list').innerHTML=state.tags.length?state.tags.map(tag=>`<article class="tag-admin-item"><span class="tag-chip" style="--tag-color:${tag.color}">${escapeHtml(tag.name)}</span><button class="icon-button danger" type="button" data-delete-tag="${tag.id}" title="Excluir">×</button></article>`).join(''):'<div class="list-empty">Nenhuma etiqueta criada.</div>';$('tags-admin-list').querySelectorAll('[data-delete-tag]').forEach(button=>button.onclick=()=>deleteTag(button.dataset.deleteTag))}
async function createTag(event){event.preventDefault();try{await api('/tags',{method:'POST',body:JSON.stringify({name:$('tag-name').value.trim(),color:$('tag-color').value})});$('tag-form').reset();$('tag-form').classList.add('hidden');await loadTags();toast('Etiqueta criada.')}catch(error){toast(error.message)}}
async function deleteTag(id){if(!confirm('Excluir esta etiqueta de todas as conversas?'))return;try{await api(`/tags/${id}`,{method:'DELETE'});if(state.tagFilter===id){state.tagFilter='';await loadInbox()}await loadTags();if(state.selected)await loadConversationTags();toast('Etiqueta excluída.')}catch(error){toast(error.message)}}
function showSection(section){const inbox=section==='inbox',contacts=section==='contacts',dashboard=section==='dashboard',onboarding=section==='onboarding',automations=section==='automations',knowledge=section==='knowledge',ai=section==='ai',whatsapp=section==='whatsapp',settings=section==='settings';document.querySelector('.inbox-panel').classList.toggle('hidden',!inbox);document.querySelector('.chat-panel').classList.toggle('hidden',!inbox);$('contacts-view').classList.toggle('hidden',!contacts);$('dashboard-view').classList.toggle('hidden',!dashboard);$('onboarding-view').classList.toggle('hidden',!onboarding);$('automation-view').classList.toggle('hidden',!automations);$('knowledge-view').classList.toggle('hidden',!knowledge);$('ai-view').classList.toggle('hidden',!ai);$('whatsapp-view').classList.toggle('hidden',!whatsapp);$('settings-view').classList.toggle('hidden',!settings);$('nav-inbox').classList.toggle('active',inbox);$('nav-contacts').classList.toggle('active',contacts);$('nav-dashboard').classList.toggle('active',dashboard);$('nav-onboarding').classList.toggle('active',onboarding);$('nav-automations').classList.toggle('active',automations);$('nav-knowledge').classList.toggle('active',knowledge);$('nav-ai').classList.toggle('active',ai);$('nav-whatsapp').classList.toggle('active',whatsapp);$('nav-settings').classList.toggle('active',settings);if(contacts)loadContacts();if(dashboard)loadDashboard();if(onboarding)loadOnboarding();if(automations)loadAutomations();if(knowledge)loadKnowledgeSources();if(ai)loadAIConfiguration();if(whatsapp)loadWhatsAppAccount();if(settings)loadOrganizationSettings()}
async function loadDashboard(){try{renderDashboard(await api('/dashboard'))}catch(error){toast(error.message)}}
async function downloadExport(type){try{const response=await fetch(`/api/v1/exports/${type}.csv`);if(!response.ok){let detail='Não foi possível exportar os dados.';try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a'),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/);link.href=url;link.download=match?.[1]||`neria-${type}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Exportação concluída.')}catch(error){toast(error.message)}}
function renderDashboard(data){$('dash-open').textContent=data.open_conversations;$('dash-human').textContent=data.waiting_human;$('dash-messages').textContent=data.messages_today;$('dash-response').textContent=data.average_first_response_minutes===null?'—':`${data.average_first_response_minutes} min`;$('dash-sla-overdue').textContent=data.sla_overdue;$('dash-contacts').textContent=data.active_contacts_30d;$('dash-closed').textContent=data.closed_conversations_30d;const max=Math.max(1,...data.daily_volume.flatMap(day=>[day.inbound,day.outbound]));$('volume-chart').innerHTML=data.daily_volume.map(day=>`<div class="chart-day"><div class="bars"><span class="bar inbound" style="height:${Math.max(3,day.inbound/max*100)}%" title="${day.inbound} recebidas"></span><span class="bar outbound" style="height:${Math.max(3,day.outbound/max*100)}%" title="${day.outbound} enviadas"></span></div><small>${new Date(`${day.date}T12:00:00`).toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</small></div>`).join('');$('team-performance-list').innerHTML=data.team_performance.length?data.team_performance.map(user=>`<div class="team-performance-row ${user.is_active?'':'inactive'}"><span><strong>${escapeHtml(user.name)}</strong><small>${user.role==='admin'?'Administrador':'Atendente'}${user.is_active?'':' · inativo'}</small></span><span>${user.open_assigned}</span><span>${user.closed_30d}</span><span>${user.messages_sent_30d}</span><span>${user.average_response_minutes===null?'—':`${user.average_response_minutes} min`}</span></div>`).join(''):'<div class="list-empty">Nenhum usuário encontrado.</div>'}
async function loadContacts(){const query=$('contacts-search').value.trim();try{state.contacts=await api(`/contacts?limit=100${query?`&search=${encodeURIComponent(query)}`:''}`);renderContacts()}catch(error){toast(error.message)}}
function contactDisplayName(contact){return contact.name||contact.profile_name||contact.phone_number}
function renderContacts(){$('contacts-list').innerHTML=state.contacts.length?state.contacts.map(contact=>`<button class="contact-item ${state.selectedContact?.id===contact.id?'active':''}" type="button" data-contact-id="${contact.id}"><div class="avatar">${initials(contactDisplayName(contact))}</div><div><strong>${escapeHtml(contactDisplayName(contact))}</strong><small>${contact.anonymized_at?'Dados anonimizados':`+${escapeHtml(contact.phone_number)}`}</small></div>${contact.is_blocked?'<span class="blocked-label">Bloqueado</span>':''}</button>`).join(''):'<div class="list-empty">Nenhum contato encontrado.</div>';$('contacts-list').querySelectorAll('[data-contact-id]').forEach(button=>button.onclick=()=>openContact(button.dataset.contactId))}
function showContactPanel(panel){['contact-empty','contact-detail','contact-create-form'].forEach(id=>$(id).classList.toggle('hidden',id!==panel))}
async function openContact(id){try{const [contact,history]=await Promise.all([api(`/contacts/${id}`),api(`/contacts/${id}/conversations`)]);state.selectedContact=contact;renderContacts();showContactPanel('contact-detail');$('contact-detail-name').textContent=contactDisplayName(contact);$('contact-detail-phone').textContent=contact.anonymized_at?'Dados pessoais removidos':`+${contact.phone_number}${contact.profile_name?` · WhatsApp: ${contact.profile_name}`:''}`;$('contact-edit-name').value=contact.name||'';$('contact-edit-form').classList.toggle('hidden',Boolean(contact.anonymized_at));$('toggle-contact-block').textContent=contact.is_blocked?'Desbloquear contato':'Bloquear contato';$('toggle-contact-block').classList.toggle('danger',!contact.is_blocked);$('toggle-contact-block').classList.toggle('hidden',Boolean(contact.anonymized_at));$('export-contact-data').classList.toggle('hidden',state.user.role!=='admin'||Boolean(contact.anonymized_at));$('anonymize-contact').classList.toggle('hidden',state.user.role!=='admin'||Boolean(contact.anonymized_at));$('contact-history').innerHTML=history.length?history.map(item=>`<button class="history-item" type="button" data-contact-conversation="${item.id}"><div><strong>${item.status==='closed'?'Conversa encerrada':'Conversa aberta'}</strong><small>${new Date(item.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</small></div><span class="mode-badge ${item.mode}">${item.mode==='human'?'Humano':'Bot'}</span></button>`).join(''):'<div class="list-empty">Nenhuma conversa registrada.</div>';$('contact-history').querySelectorAll('[data-contact-conversation]').forEach(button=>button.onclick=()=>openConversationFromContact(button.dataset.contactConversation))}catch(error){toast(error.message)}}
async function exportSelectedContact(){if(!state.selectedContact)return;try{const response=await fetch(`/api/v1/privacy/contacts/${state.selectedContact.id}/export`);if(!response.ok)throw new Error((await response.json()).detail||'Não foi possível exportar os dados.');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`neria-contato-${state.selectedContact.id}.json`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Dados do contato exportados.')}catch(error){toast(error.message)}}
async function anonymizeSelectedContact(){if(!state.selectedContact)return;const confirmation=prompt('Esta ação remove permanentemente os dados pessoais e o conteúdo das mensagens. Digite ANONIMIZAR para continuar.');if(confirmation!=='ANONIMIZAR')return;try{await api(`/privacy/contacts/${state.selectedContact.id}/anonymize`,{method:'POST',body:JSON.stringify({confirmation})});await loadContacts();await openContact(state.selectedContact.id);toast('Contato anonimizado.')}catch(error){toast(error.message)}}
async function previewRetention(){try{const data=await api('/privacy/retention/preview');$('retention-preview').textContent=data.conversations_eligible?`${data.conversations_eligible} conversa(s) encerrada(s) antes de ${new Date(data.cutoff).toLocaleDateString('pt-BR')} estão elegíveis para limpeza.`:'Nenhuma conversa está elegível para limpeza.';$('run-retention').classList.toggle('hidden',data.conversations_eligible===0)}catch(error){toast(error.message)}}
async function runRetention(){const confirmation=prompt('O conteúdo antigo será removido permanentemente. Digite LIMPAR para continuar.');if(confirmation!=='LIMPAR')return;try{const data=await api('/privacy/retention/run',{method:'POST',body:JSON.stringify({confirmation})});$('retention-preview').textContent=data.conversations_remaining?`${data.conversations_sanitized} conversa(s) foram limpas; ${data.conversations_remaining} ainda aguardam outra execução.`:`${data.conversations_sanitized} conversa(s) foram limpas.`;$('run-retention').classList.toggle('hidden',data.conversations_remaining===0);toast('Política de retenção executada.')}catch(error){toast(error.message)}}
async function createContact(event){event.preventDefault();const payload={name:$('contact-create-name').value.trim()||null,phone_number:$('contact-create-phone').value.replace(/\D/g,'')};try{const contact=await api('/contacts',{method:'POST',body:JSON.stringify(payload)});$('contact-create-form').reset();await loadContacts();await openContact(contact.id);toast('Contato cadastrado.')}catch(error){toast(error.message)}}
async function saveContactName(event){event.preventDefault();if(!state.selectedContact)return;try{state.selectedContact=await api(`/contacts/${state.selectedContact.id}`,{method:'PATCH',body:JSON.stringify({name:$('contact-edit-name').value.trim()||null})});await loadContacts();await openContact(state.selectedContact.id);toast('Nome atualizado.')}catch(error){toast(error.message)}}
async function toggleContactBlock(){if(!state.selectedContact)return;const blocked=!state.selectedContact.is_blocked;try{state.selectedContact=await api(`/contacts/${state.selectedContact.id}`,{method:'PATCH',body:JSON.stringify({is_blocked:blocked})});await loadContacts();await openContact(state.selectedContact.id);toast(blocked?'Contato bloqueado.':'Contato desbloqueado.')}catch(error){toast(error.message)}}
async function openConversationFromContact(id){const inboxConversation=state.conversations.find(item=>item.id===id);try{const conversation=inboxConversation||await api(`/conversations/${id}`);if(!inboxConversation){conversation.contact_name=contactDisplayName(state.selectedContact);conversation.contact_phone=state.selectedContact.phone_number}showSection('inbox');await displayConversation(conversation,{markRead:conversation.status!=='closed'})}catch(error){toast(error.message)}}
async function loadOnboarding(autoOpen=false){try{state.onboarding=await api('/onboarding');renderOnboarding();const seenKey=`neria_onboarding_seen_${state.user.organization_id}`;if(autoOpen&&!state.onboarding.is_complete&&!localStorage.getItem(seenKey))showSection('onboarding')}catch(error){toast(error.message)}}
function renderOnboarding(){const data=state.onboarding;$('onboarding-percent').textContent=`${data.progress_percent}%`;$('onboarding-count').textContent=`${data.completed_required} de ${data.total_required} etapas essenciais`;$('onboarding-bar').style.width=`${data.progress_percent}%`;$('onboarding-steps').innerHTML=data.steps.map((step,index)=>`<article class="onboarding-step ${step.completed?'completed':''}"><span class="step-status">${step.completed?'✓':index+1}</span><div><div class="step-title"><strong>${escapeHtml(step.title)}</strong>${step.required?'':'<small>OPCIONAL</small>'}</div><p>${escapeHtml(step.description)}</p></div><button class="secondary" type="button" data-onboarding-section="${step.section}">${step.completed?'Revisar':'Configurar'}</button></article>`).join('');$('onboarding-steps').querySelectorAll('[data-onboarding-section]').forEach(button=>button.onclick=()=>showSection(button.dataset.onboardingSection))}
async function loadAIConfiguration(){try{const [config,suggestions,metrics,runs]=await Promise.all([api('/ai/configuration'),api('/ai/knowledge-suggestions'),api('/ai/metrics'),api('/ai/runs?limit=10')]);$('ai-enabled').checked=config.is_enabled;$('ai-tone').value=config.tone;$('ai-confidence').value=config.minimum_confidence;$('ai-history-limit').value=config.history_message_limit;$('ai-retrieval-limit').value=config.retrieval_limit;$('ai-instructions').value=config.instructions||'';$('ai-fallback').value=config.fallback_message;renderKnowledgeSuggestions(suggestions);renderAIMetrics(metrics);renderAIRuns(runs)}catch(error){toast(error.message)}}
function renderAIMetrics(metrics){$('metric-total').textContent=metrics.total_runs;$('metric-confidence').textContent=metrics.average_confidence===null?'—':`${metrics.average_confidence}%`;$('metric-handoff').textContent=`${metrics.handoff_rate}%`;$('metric-handoff-count').textContent=`${metrics.escalated_runs} atendimento${metrics.escalated_runs===1?'':'s'}`;$('metric-corrections').textContent=metrics.correction_feedback;$('metric-quota-remaining').textContent=metrics.daily_requests_remaining;const card=$('metric-quota-card'),tokens=`${metrics.daily_total_tokens.toLocaleString('pt-BR')} de ${metrics.daily_token_limit.toLocaleString('pt-BR')} tokens`,status=metrics.daily_quota_status==='exhausted'||metrics.daily_token_quota_status==='exhausted'?'exhausted':metrics.daily_quota_status==='warning'||metrics.daily_token_quota_status==='warning'?'warning':'normal',percent=Math.max(metrics.daily_quota_percent,metrics.daily_token_quota_percent),labels={normal:`${metrics.paid_requests_today} de ${metrics.daily_request_limit} chamadas • ${tokens}`,warning:`Atenção: ${percent}% da cota comprometida • ${tokens}`,exhausted:`Cota esgotada • ${tokens}; novas dúvidas serão transferidas`};card.classList.remove('quota-warning','quota-exhausted');if(status!=='normal')card.classList.add(`quota-${status}`);$('metric-quota-usage').textContent=labels[status];renderAIUsageHistory(metrics.daily_usage||[]);renderAIPromptVersions(metrics.prompt_versions||[])}
function renderAIPromptVersions(versions){$('ai-version-metrics').innerHTML=versions.length?versions.map(version=>{const evaluated=version.helpful_feedback+version.correction_feedback,approval=evaluated?Math.round(version.helpful_feedback/evaluated*100):null,handoff=version.total_runs?Math.round(version.escalated_runs/version.total_runs*100):0;return`<article class="ai-version-row"><div class="ai-version-name"><strong>${escapeHtml(version.prompt_version)}</strong><span>${version.total_runs} resposta${version.total_runs===1?'':'s'}</span></div><div><small>CONFIANÇA</small><strong>${version.average_confidence===null?'—':`${version.average_confidence}%`}</strong></div><div><small>TRANSFERÊNCIA</small><strong>${handoff}%</strong></div><div><small>APROVAÇÃO</small><strong>${approval===null?'—':`${approval}%`}</strong></div><div><small>FALHAS</small><strong>${version.failed_runs}</strong></div></article>`}).join(''):'<div class="list-empty">Nenhuma execução registrada no período.</div>'}
function renderAIRuns(runs){const statusLabels={pending:'Pendente',processing:'Processando',completed:'Respondida',escalated:'Transferida',failed:'Falhou'},errorLabels={provider_authentication_failed:'Falha de autenticação',provider_quota_exhausted:'Créditos esgotados',provider_rate_limited:'Limite temporário',provider_timeout:'Tempo esgotado',provider_unavailable:'Provedor indisponível',provider_request_rejected:'Requisição recusada',provider_http_error:'Erro do provedor',provider_error:'Falha inesperada',worker_interrupted:'Processamento interrompido'};$('ai-runs-list').innerHTML=runs.length?runs.map(run=>{const tokens=(run.input_tokens||0)+(run.output_tokens||0),date=new Date(run.created_at).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});return`<article class="ai-run-row"><div><span class="status-pill ai-run-${run.status}">${statusLabels[run.status]||run.status}</span><small>${date}</small></div><div><small>MODELO E PROMPT</small><strong>${escapeHtml(run.model||'Processamento local')}</strong><span>${escapeHtml(run.prompt_version)}</span></div><div><small>DESEMPENHO</small><strong>${run.confidence===null?'—':`${run.confidence}% confiança`}</strong><span>${run.latency_ms===null?'—':`${run.latency_ms} ms`}</span></div><div><small>CONSUMO</small><strong>${tokens.toLocaleString('pt-BR')} tokens</strong><span>${run.source_count} fonte${run.source_count===1?'':'s'}</span></div>${run.error?`<div class="ai-run-error"><small>DIAGNÓSTICO</small><strong>${escapeHtml(errorLabels[run.error]||'Falha controlada')}</strong><span>${escapeHtml(run.error)}</span></div>`:''}</article>`}).join(''):'<div class="list-empty">Nenhuma execução registrada.</div>'}
function renderAIUsageHistory(history){const max=Math.max(1,...history.map(item=>item.total_tokens)),tokens=history.reduce((sum,item)=>sum+item.total_tokens,0),requests=history.reduce((sum,item)=>sum+item.paid_requests,0);$('metric-period-tokens').textContent=tokens.toLocaleString('pt-BR');$('metric-period-requests').textContent=`${requests} chamada${requests===1?'':'s'} paga${requests===1?'':'s'}`;$('ai-usage-chart').innerHTML=history.map(item=>{const height=item.total_tokens?Math.max(5,Math.round(item.total_tokens/max*100)):2,date=new Date(`${item.date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),title=`${date}: ${item.total_tokens} tokens, ${item.paid_requests} chamada${item.paid_requests===1?'':'s'}`;return`<span class="ai-usage-column" title="${title}" aria-label="${title}"><i style="height:${height}%"></i></span>`}).join('')}
async function saveAIConfiguration(event){event.preventDefault();const payload={is_enabled:$('ai-enabled').checked,tone:$('ai-tone').value.trim(),minimum_confidence:Number($('ai-confidence').value),history_message_limit:Number($('ai-history-limit').value),retrieval_limit:Number($('ai-retrieval-limit').value),instructions:$('ai-instructions').value.trim()||null,fallback_message:$('ai-fallback').value.trim()};try{await api('/ai/configuration',{method:'PATCH',body:JSON.stringify(payload)});toast('Configurações da IA salvas.')}catch(error){toast(error.message)}}
async function runAISimulation(){const question=$('simulation-question').value.trim();if(question.length<3){toast('Digite uma pergunta para simular.');return}const button=$('run-simulation');button.disabled=true;button.textContent='Simulando…';try{const result=await api('/ai/simulate',{method:'POST',body:JSON.stringify({question})}),routes={local:'Resposta local',provider:'Usaria IA',handoff:'Transferir'},reasons={structured_company_profile:'Informação disponível no perfil da empresa',relevant_knowledge_found:'Base relevante encontrada; o modelo redigiria a resposta',no_relevant_knowledge:'Não há informação suficiente na base',daily_ai_limit_reached:'Limite diário de IA atingido'},sources=result.sources.map(source=>`<article><strong>${escapeHtml(source.title)}</strong><p>${escapeHtml(source.content)}</p></article>`).join('');$('simulation-result').innerHTML=`<div class="simulation-summary"><span class="status-pill ${result.route==='handoff'?'':'active'}">${routes[result.route]||result.route}</span><strong>Confiança: ${result.confidence}%</strong></div><p class="simulation-route-reason">${escapeHtml(reasons[result.reason]||result.reason)} • Nenhuma chamada externa realizada</p><div class="simulation-answer">${escapeHtml(result.answer)}</div><h4>${sources?'Fontes encontradas':'Nenhuma fonte encontrada'}</h4>${sources}`;$('simulation-result').classList.remove('hidden')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Simular resposta'}}
function renderKnowledgeSuggestions(suggestions){const pending=suggestions.filter(item=>item.status==='pending');$('suggestions-list').innerHTML=pending.length?pending.map(item=>`<article class="suggestion-card"><div class="suggestion-question"><small>PERGUNTA DO CLIENTE</small><strong>${escapeHtml(item.question)}</strong></div><div class="suggestion-answer"><small>RESPOSTA CORRIGIDA</small><p>${escapeHtml(item.suggested_content)}</p></div><div class="suggestion-actions"><button class="secondary danger" type="button" data-reject-suggestion="${item.id}">Rejeitar</button><button class="primary" type="button" data-approve-suggestion="${item.id}">Aprovar e ensinar</button></div></article>`).join(''):'<div class="learning-empty"><span>✓</span><strong>Nenhuma correção pendente</strong><p>As respostas corrigidas pela equipe aparecerão aqui.</p></div>';$('suggestions-list').querySelectorAll('[data-approve-suggestion]').forEach(button=>button.onclick=()=>reviewKnowledgeSuggestion(button.dataset.approveSuggestion,'approve'));$('suggestions-list').querySelectorAll('[data-reject-suggestion]').forEach(button=>button.onclick=()=>reviewKnowledgeSuggestion(button.dataset.rejectSuggestion,'reject'))}
async function refreshKnowledgeSuggestions(){try{renderKnowledgeSuggestions(await api('/ai/knowledge-suggestions'))}catch(error){toast(error.message)}}
async function reviewKnowledgeSuggestion(id,action){try{await api(`/ai/knowledge-suggestions/${id}/${action}`,{method:'POST'});await refreshKnowledgeSuggestions();toast(action==='approve'?'Correção aprovada e adicionada à base.':'Correção rejeitada.')}catch(error){toast(error.message)}}
async function loadWhatsAppAccount(){try{const accounts=await api('/whatsapp-accounts');state.whatsappAccount=accounts[0]||null;$('whatsapp-empty').classList.toggle('hidden',!!state.whatsappAccount);$('whatsapp-connected').classList.toggle('hidden',!state.whatsappAccount);if(!state.whatsappAccount)return;renderWhatsAppAccount();await loadWhatsAppTemplates()}catch(error){toast(error.message)}}
function renderWhatsAppAccount(){const account=state.whatsappAccount;$('wa-account-name').textContent=account.display_name;$('wa-account-phone').textContent=`+${account.phone_number}`;$('wa-account-phone-id').textContent=account.meta_phone_number_id||'—';$('wa-account-business-id').textContent=account.meta_business_account_id||'—';$('wa-account-status').textContent={active:'Conectada',pending:'Pendente',disconnected:'Desconectada'}[account.status]||account.status;$('wa-account-status').className=`status-pill ${account.status==='active'?'active':''}`;$('verify-whatsapp').classList.toggle('hidden',account.status==='active');$('webhook-url').textContent=`${window.location.origin}/api/v1/webhooks/whatsapp`}
async function createWhatsAppAccount(event){event.preventDefault();const button=event.submitter;button.disabled=true;const payload={display_name:$('wa-display-name').value.trim(),phone_number:$('wa-phone').value.replace(/\D/g,''),meta_phone_number_id:$('wa-phone-id').value.trim(),meta_business_account_id:$('wa-business-id').value.trim(),access_token:$('wa-access-token').value.trim()};try{state.whatsappAccount=await api('/whatsapp-accounts',{method:'POST',body:JSON.stringify(payload)});$('whatsapp-form').reset();renderWhatsAppAccount();$('whatsapp-empty').classList.add('hidden');$('whatsapp-connected').classList.remove('hidden');await loadWhatsAppTemplates();toast('Conta salva. Agora valide as credenciais.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function verifyWhatsAppAccount(){if(!state.whatsappAccount)return;const button=$('verify-whatsapp');button.disabled=true;try{state.whatsappAccount=await api(`/whatsapp-accounts/${state.whatsappAccount.id}/verify`,{method:'POST'});renderWhatsAppAccount();toast('WhatsApp conectado com sucesso.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function loadWhatsAppTemplates(){if(!state.whatsappAccount)return;try{renderWhatsAppTemplates(await api(`/whatsapp-accounts/${state.whatsappAccount.id}/templates`))}catch(error){toast(error.message)}}
function renderWhatsAppTemplates(templates){$('template-list').innerHTML=templates.length?templates.map(template=>`<div class="template-item"><div><strong>${escapeHtml(template.name)}</strong><small>${escapeHtml(template.language)}${template.category?` · ${escapeHtml(template.category)}`:''}</small></div><span class="status-pill ${template.status==='approved'?'active':''}">${{approved:'Aprovado',pending:'Pendente',rejected:'Rejeitado',paused:'Pausado'}[template.status]||template.status}</span></div>`).join(''):'<div class="list-empty">Nenhum template sincronizado.</div>'}
async function syncWhatsAppTemplates(){if(!state.whatsappAccount)return;const button=$('sync-templates');button.disabled=true;try{renderWhatsAppTemplates(await api(`/whatsapp-accounts/${state.whatsappAccount.id}/templates/sync`,{method:'POST'}));toast('Templates sincronizados.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function loadOrganizationSettings(){try{const [profile,users,auditLogs,subscription,quickReplies]=await Promise.all([api('/organization/profile'),api('/users'),api('/audit-logs'),api('/billing/subscription'),api('/quick-replies')]);state.users=users;state.quickReplies=quickReplies;$('company-name').value=profile.company_name;$('company-email').value=profile.contact_email||'';$('company-phone').value=profile.contact_phone||'';$('company-address').value=profile.address||'';$('company-description').value=profile.description||'';$('company-hours').value=profile.opening_hours||'';$('company-welcome').value=profile.welcome_message;$('company-sla').value=profile.sla_first_response_minutes;$('company-retention').value=profile.data_retention_days;$('company-auto-assignment').checked=profile.auto_assignment_enabled;renderTeam();renderAssignees();renderAuditLogs(auditLogs);renderSubscription(subscription);renderQuickReplyMenu();renderQuickRepliesAdmin()}catch(error){toast(error.message)}}
async function saveCompanyProfile(event){event.preventDefault();const payload={company_name:$('company-name').value.trim(),contact_email:$('company-email').value.trim()||null,contact_phone:$('company-phone').value.trim()||null,address:$('company-address').value.trim()||null,description:$('company-description').value.trim()||null,opening_hours:$('company-hours').value.trim()||null,welcome_message:$('company-welcome').value.trim(),sla_first_response_minutes:Number($('company-sla').value),data_retention_days:Number($('company-retention').value),auto_assignment_enabled:$('company-auto-assignment').checked};try{await api('/organization/profile',{method:'PATCH',body:JSON.stringify(payload)});await loadInbox();toast('Dados da empresa atualizados.')}catch(error){toast(error.message)}}
function renderTeam(){const active=state.users.filter(user=>user.is_active).length;$('team-limit').textContent=`${active} de 3 acessos ativos`;$('new-user').disabled=active>=3;$('team-list').innerHTML=state.users.map(user=>`<article class="team-member ${user.is_active?'':'inactive'}"><div class="avatar">${initials(user.name)}</div><div class="team-identity"><strong>${escapeHtml(user.name)}</strong><small>${escapeHtml(user.email)}</small></div><select data-user-role="${user.id}" ${user.id===state.user.id?'disabled':''}><option value="agent" ${user.role==='agent'?'selected':''}>Atendente</option><option value="admin" ${user.role==='admin'?'selected':''}>Administrador</option></select><label class="assignment-toggle"><input type="checkbox" data-user-assignments="${user.id}" ${user.accepts_assignments?'checked':''} ${user.is_active?'':'disabled'}>Recebe fila</label><button class="secondary ${user.is_active?'danger':''}" type="button" data-toggle-user="${user.id}" ${user.id===state.user.id?'disabled':''}>${user.is_active?'Desativar':'Reativar'}</button></article>`).join('');$('team-list').querySelectorAll('[data-user-role]').forEach(select=>select.onchange=()=>updateTeamMember(select.dataset.userRole,{role:select.value}));$('team-list').querySelectorAll('[data-user-assignments]').forEach(input=>input.onchange=()=>updateTeamMember(input.dataset.userAssignments,{accepts_assignments:input.checked}));$('team-list').querySelectorAll('[data-toggle-user]').forEach(button=>button.onclick=()=>{const user=state.users.find(item=>item.id===button.dataset.toggleUser);updateTeamMember(user.id,{is_active:!user.is_active})})}
async function createTeamMember(event){event.preventDefault();const payload={name:$('new-user-name').value.trim(),email:$('new-user-email').value.trim(),password:$('new-user-password').value,role:$('new-user-role').value};try{await api('/users',{method:'POST',body:JSON.stringify(payload)});$('user-form').reset();$('user-form').classList.add('hidden');await loadOrganizationSettings();toast('Usuário criado.')}catch(error){toast(error.message)}}
async function updateTeamMember(id,changes){try{await api(`/users/${id}`,{method:'PATCH',body:JSON.stringify(changes)});await loadOrganizationSettings();toast('Acesso atualizado.')}catch(error){toast(error.message);await loadOrganizationSettings()}}
async function loadQuickReplies(){try{state.quickReplies=await api('/quick-replies');renderQuickReplyMenu();if(state.user?.role==='admin')renderQuickRepliesAdmin()}catch(error){toast(error.message)}}
function renderQuickReplyMenu(filter=''){const term=filter.replace(/^\//,'').toLowerCase(),items=state.quickReplies.filter(item=>!term||item.shortcut.includes(term)||item.title.toLowerCase().includes(term));$('quick-replies-menu').innerHTML=items.length?items.map(item=>`<button type="button" data-quick-reply="${item.id}"><span><strong>${escapeHtml(item.title)}</strong><small>/${escapeHtml(item.shortcut)}</small></span><p>${escapeHtml(item.content)}</p></button>`).join(''):'<div class="list-empty">Nenhuma resposta encontrada.</div>';$('quick-replies-menu').querySelectorAll('[data-quick-reply]').forEach(button=>button.onclick=()=>insertQuickReply(button.dataset.quickReply))}
function insertQuickReply(id){const reply=state.quickReplies.find(item=>item.id===id);if(!reply)return;$('message-input').value=reply.content;$('quick-replies-menu').classList.add('hidden');$('message-input').focus()}
function renderQuickRepliesAdmin(){$('quick-replies-admin-list').innerHTML=state.quickReplies.length?state.quickReplies.map(item=>`<article class="quick-reply-admin-item"><div><strong>${escapeHtml(item.title)}</strong><small>/${escapeHtml(item.shortcut)}</small><p>${escapeHtml(item.content)}</p></div><button class="icon-button danger" type="button" data-delete-quick-reply="${item.id}" title="Excluir">×</button></article>`).join(''):'<div class="list-empty">Nenhuma resposta rápida criada.</div>';$('quick-replies-admin-list').querySelectorAll('[data-delete-quick-reply]').forEach(button=>button.onclick=()=>deleteQuickReply(button.dataset.deleteQuickReply))}
async function createQuickReply(event){event.preventDefault();const payload={title:$('quick-reply-title').value.trim(),shortcut:$('quick-reply-shortcut').value.trim().replace(/^\//,''),content:$('quick-reply-content').value.trim()};try{await api('/quick-replies',{method:'POST',body:JSON.stringify(payload)});$('quick-reply-form').reset();$('quick-reply-form').classList.add('hidden');await loadQuickReplies();toast('Resposta rápida criada.')}catch(error){toast(error.message)}}
async function deleteQuickReply(id){if(!confirm('Excluir esta resposta rápida?'))return;try{await api(`/quick-replies/${id}`,{method:'DELETE'});await loadQuickReplies();toast('Resposta rápida excluída.')}catch(error){toast(error.message)}}
function auditActionLabel(action){return {'auth.login_succeeded':'Login realizado','auth.login_failed':'Tentativa de login recusada','auth.password_reset_requested':'Recuperação de senha solicitada','auth.password_reset_completed':'Senha redefinida','organization.profile_updated':'Dados da empresa atualizados','user.created':'Usuário criado','user.updated':'Acesso de usuário alterado','contact.updated':'Contato atualizado','whatsapp.account_created':'Conta do WhatsApp cadastrada','whatsapp.account_verified':'Conta do WhatsApp validada','whatsapp.templates_synced':'Templates do WhatsApp sincronizados','billing.subscription_updated':'Assinatura atualizada'}[action]||action}
function renderSubscription(subscription){const labels={trialing:'Período de teste',active:'Ativa',past_due:'Pagamento pendente',suspended:'Suspensa',canceled:'Cancelada'},dates={trialing:subscription.trial_ends_at,active:subscription.current_period_ends_at,past_due:subscription.current_period_ends_at};$('subscription-status').textContent=labels[subscription.status]||subscription.status;$('subscription-status').className=`status-pill ${['trialing','active'].includes(subscription.status)?'active':''}`;$('subscription-description').textContent=subscription.status==='trialing'?'Teste gratuito com os recursos essenciais do plano inicial.':'Assinatura gerenciada manualmente nesta fase.';const date=dates[subscription.status];$('subscription-date').textContent=date?`Válida até ${new Date(date).toLocaleDateString('pt-BR')}`:'Sem data de renovação definida'}
function renderAuditLogs(logs){$('audit-list').innerHTML=logs.length?logs.map(log=>`<article class="audit-item"><span class="audit-dot"></span><div><strong>${escapeHtml(auditActionLabel(log.action))}</strong><small>${escapeHtml(log.actor_name||'Sistema')} · ${new Date(log.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</small></div></article>`).join(''):'<div class="list-empty">Nenhum evento registrado.</div>'}
async function refreshAuditLogs(){try{renderAuditLogs(await api('/audit-logs'))}catch(error){toast(error.message)}}
async function loadAutomations(){try{state.automations=await api('/automations');renderAutomationList()}catch(error){toast(error.message)}}
function renderAutomationList(){$('automation-list').innerHTML=state.automations.length?state.automations.map(item=>`<button class="automation-list-item ${state.selectedAutomation?.id===item.id?'active':''}" data-automation-id="${item.id}"><strong>${escapeHtml(item.name)}</strong><small><span>Versão ${item.version}</span><span class="${item.status==='active'?'active-label':''}">${{active:'Ativa',draft:'Rascunho',inactive:'Inativa'}[item.status]}</span></small></button>`).join(''):'<div class="list-empty">Nenhuma automação criada.</div>';$('automation-list').querySelectorAll('[data-automation-id]').forEach(button=>button.onclick=()=>editAutomation(button.dataset.automationId))}
function addAutomationOption(data={}){if($('automation-options').children.length>=3){toast('O menu permite no máximo 3 opções.');return}const card=document.createElement('div');card.className='option-card';card.innerHTML=`<label>Nome da opção<input class="option-title" maxlength="20" required placeholder="Ex.: Comprar" value="${escapeHtml(data.title||'')}"></label><label>Resposta<input class="option-response" maxlength="1000" required placeholder="Mensagem enviada ao cliente" value="${escapeHtml(data.response||'')}"></label><label>Destino<select class="option-action"><option value="message" ${data.action!=='handoff'?'selected':''}>Responder</option><option value="handoff" ${data.action==='handoff'?'selected':''}>Atendente humano</option></select></label><button class="icon-button remove-option" type="button" title="Remover">×</button>`;card.querySelector('.remove-option').onclick=()=>{if($('automation-options').children.length===1){toast('O menu precisa ter ao menos uma opção.');return}card.remove()};$('automation-options').appendChild(card)}
function newAutomation(){state.selectedAutomation=null;$('automation-empty').classList.add('hidden');$('automation-form').classList.remove('hidden');$('automation-title').textContent='Nova automação';$('automation-status').textContent='Rascunho';$('automation-status').className='status-pill';$('automation-name').value='';$('automation-keywords').value='';$('automation-fallback').checked=false;$('menu-text').value='';$('automation-options').innerHTML='';addAutomationOption();$('deactivate-automation').classList.add('hidden');renderAutomationList();$('automation-name').focus()}
function editAutomation(id){const item=state.automations.find(value=>value.id===id);if(!item)return;state.selectedAutomation=item;$('automation-empty').classList.add('hidden');$('automation-form').classList.remove('hidden');$('automation-title').textContent=item.name;$('automation-status').textContent={active:'Ativa',draft:'Rascunho',inactive:'Inativa'}[item.status];$('automation-status').className=`status-pill ${item.status}`;$('automation-name').value=item.name;$('automation-keywords').value=item.trigger_keywords.join(', ');$('automation-fallback').checked=item.is_fallback;const start=item.definition.nodes[item.definition.start_node_id]||{};$('menu-text').value=start.text||'';$('automation-options').innerHTML='';(start.options||[]).forEach(option=>{const target=item.definition.nodes[option.next_node_id]||{};addAutomationOption({title:option.title,response:target.text||'',action:target.type==='handoff'?'handoff':'message'})});if(!start.options?.length)addAutomationOption();$('deactivate-automation').classList.toggle('hidden',item.status!=='active');renderAutomationList()}
function automationPayload(){const nodes={},options=[];[...$('automation-options').children].forEach((card,index)=>{const title=card.querySelector('.option-title').value.trim(),response=card.querySelector('.option-response').value.trim(),action=card.querySelector('.option-action').value,nodeId=`option_${index+1}`;options.push({id:`option_${index+1}`,title,next_node_id:nodeId});nodes[nodeId]=action==='handoff'?{type:'handoff',text:response}:{type:'message',text:response,next_node_id:'finish'}});nodes.main_menu={type:'menu',text:$('menu-text').value.trim(),options};nodes.finish={type:'end'};return{name:$('automation-name').value.trim(),trigger_keywords:$('automation-keywords').value.split(',').map(value=>value.trim()).filter(Boolean),is_fallback:$('automation-fallback').checked,definition:{start_node_id:'main_menu',nodes}}}
async function saveAutomation(activate=false){try{const payload=automationPayload();let saved;if(state.selectedAutomation){saved=await api(`/automations/${state.selectedAutomation.id}`,{method:'PATCH',body:JSON.stringify(payload)})}else{saved=await api('/automations',{method:'POST',body:JSON.stringify(payload)})}if(activate)saved=await api(`/automations/${saved.id}/activate`,{method:'POST'});state.selectedAutomation=saved;await loadAutomations();editAutomation(saved.id);toast(activate?'Automação ativada.':'Rascunho salvo.')}catch(error){toast(error.message)}}
async function deactivateAutomation(){if(!state.selectedAutomation)return;try{const saved=await api(`/automations/${state.selectedAutomation.id}/deactivate`,{method:'POST'});state.selectedAutomation=saved;await loadAutomations();editAutomation(saved.id);toast('Automação desativada.')}catch(error){toast(error.message)}}
async function loadKnowledgeSources(){try{state.knowledgeSources=await api('/knowledge/sources');renderKnowledgeList();renderKnowledgeEmptyState();if(!state.selectedSource||!state.knowledgeSources.some(source=>source.id===state.selectedSource.id))showKnowledgePanel('knowledge-empty')}catch(error){toast(error.message)}}
function renderKnowledgeEmptyState(){const hasSources=state.knowledgeSources.length>0;$('knowledge-empty-title').textContent=hasSources?'Selecione uma fonte':'Sua base está vazia';$('knowledge-empty-description').textContent=hasSources?'Escolha uma fonte ao lado para visualizar o conteúdo processado.':'Adicione informações ou envie um documento.'}
function renderKnowledgeList(){$('knowledge-list').innerHTML=state.knowledgeSources.length?state.knowledgeSources.map(source=>`<button class="knowledge-item ${state.selectedSource?.id===source.id?'active':''}" data-source-id="${source.id}"><span class="source-icon">${source.source_type==='manual'?'Aa':fileExtension(source.filename)}</span><span><strong>${escapeHtml(source.title)}</strong><small>${source.source_type==='manual'?'Texto manual':escapeHtml(source.filename||'Documento')} · ${formatCharacters(source.character_count)}</small></span></button>`).join(''):'<div class="list-empty">Nenhuma fonte cadastrada.</div>';$('knowledge-list').querySelectorAll('[data-source-id]').forEach(button=>button.onclick=()=>openKnowledgeSource(button.dataset.sourceId))}
function fileExtension(filename=''){return filename.split('.').pop().slice(0,4).toUpperCase()||'DOC'}
function formatCharacters(value){return new Intl.NumberFormat('pt-BR').format(value)+' caracteres'}
function showKnowledgePanel(panel){['knowledge-empty','knowledge-detail','manual-source-form','file-source-form'].forEach(id=>$(id).classList.toggle('hidden',id!==panel))}
function newManualSource(){state.selectedSource=null;showKnowledgePanel('manual-source-form');$('manual-source-form').reset();$('manual-title').focus();renderKnowledgeList()}
function newFileSource(){state.selectedSource=null;showKnowledgePanel('file-source-form');$('file-source-form').reset();$('selected-file').textContent='TXT, PDF ou DOCX · máximo de 10 MB';renderKnowledgeList()}
async function openKnowledgeSource(id){const source=state.knowledgeSources.find(item=>item.id===id);if(!source)return;state.selectedSource=source;showKnowledgePanel('knowledge-detail');$('knowledge-title').textContent=source.title;$('knowledge-meta').textContent=source.filename||'Informação cadastrada manualmente';$('knowledge-characters').textContent=new Intl.NumberFormat('pt-BR').format(source.character_count);$('knowledge-type').textContent=source.source_type==='manual'?'Manual':fileExtension(source.filename);$('knowledge-content').innerHTML='<div class="list-empty">Carregando conteúdo…</div>';renderKnowledgeList();try{const chunks=await api(`/knowledge/sources/${source.id}/chunks`);$('knowledge-chunks').textContent=chunks.length;$('knowledge-content').innerHTML=chunks.map(chunk=>`<article class="chunk-card"><small>TRECHO ${chunk.position+1}</small>${escapeHtml(chunk.content)}</article>`).join('')}catch(error){toast(error.message)}}
async function createManualKnowledge(event){event.preventDefault();const button=event.submitter;button.disabled=true;try{const source=await api('/knowledge/sources/manual',{method:'POST',body:JSON.stringify({title:$('manual-title').value.trim(),content:$('manual-content').value.trim()})});await loadKnowledgeSources();await openKnowledgeSource(source.id);toast('Informação adicionada à base.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function createFileKnowledge(event){event.preventDefault();const file=$('knowledge-file').files[0],button=event.submitter;if(!file)return;button.disabled=true;button.textContent='Processando…';const formData=new FormData();formData.append('file',file);if($('file-title').value.trim())formData.append('title',$('file-title').value.trim());try{let response;try{response=await fetch('/api/v1/knowledge/sources/upload',{method:'POST',headers:{'X-CSRF-Token':csrfToken()},body:formData})}catch{throw new Error('Não foi possível enviar o arquivo. Verifique sua internet e tente novamente.')}if(response.status===401){showLoggedOut();throw new Error('Sua sessão expirou. Entre novamente.')}if(!response.ok){let detail=null;try{detail=apiErrorDetail((await response.json()).detail)}catch{}let message=detail||'Não foi possível processar o arquivo. Verifique o formato e o tamanho.';if(response.status>=500){const requestId=response.headers.get('X-Request-ID');message+=` Tente novamente em instantes.${requestId?` Código de suporte: ${requestId}.`:''}`}throw new Error(message)}const source=await response.json();await loadKnowledgeSources();await openKnowledgeSource(source.id);toast('Documento processado com sucesso.')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Enviar e processar'}}
async function deleteKnowledgeSource(){if(!state.selectedSource||!confirm(`Excluir "${state.selectedSource.title}" da base de conhecimento?`))return;try{await api(`/knowledge/sources/${state.selectedSource.id}`,{method:'DELETE'});state.selectedSource=null;await loadKnowledgeSources();showKnowledgePanel('knowledge-empty');toast('Fonte excluída.')}catch(error){toast(error.message)}}
async function sendMessage(event){event.preventDefault();const input=$('message-input'),body=input.value.trim(),conversationId=state.selected.id;if(!body)return;input.disabled=true;const pending=state.pendingMessage;if(!pending||pending.body!==body||pending.conversationId!==conversationId)state.pendingMessage={body,conversationId,key:crypto.randomUUID()};try{await api(`/conversations/${conversationId}/messages`,{method:'POST',headers:{'Idempotency-Key':state.pendingMessage.key},body:JSON.stringify({body})});state.pendingMessage=null;input.value='';await loadMessages();await loadInbox(false)}catch(error){toast(error.message)}finally{input.disabled=false;input.focus()}}
$('login-form').onsubmit=login;$('logout').onclick=logout;$('refresh').onclick=()=>loadInbox();$('search').oninput=renderConversations;$('filters').querySelectorAll('button').forEach(button=>button.onclick=()=>{state.filter=button.dataset.filter;$('filters').querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));renderConversations()});$('composer').onsubmit=sendMessage;$('toggle-mode').onclick=()=>patchConversation({mode:state.selected.mode==='bot'?'human':'bot'});$('assignee').onchange=event=>patchConversation({assigned_user_id:event.target.value||null});$('close-conversation').onclick=()=>patchConversation({status:'closed'});$('back').onclick=()=>$('app-view').classList.remove('chat-open');$('message-input').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('composer').requestSubmit()}};$('nav-inbox').onclick=()=>showSection('inbox');$('nav-automations').onclick=()=>showSection('automations');$('nav-knowledge').onclick=()=>showSection('knowledge');$('nav-ai').onclick=()=>showSection('ai');$('nav-whatsapp').onclick=()=>showSection('whatsapp');$('new-automation').onclick=newAutomation;$('add-option').onclick=()=>addAutomationOption();$('automation-form').onsubmit=event=>{event.preventDefault();saveAutomation(false)};$('activate-automation').onclick=()=>saveAutomation(true);$('deactivate-automation').onclick=deactivateAutomation;$('new-manual-source').onclick=newManualSource;$('new-file-source').onclick=newFileSource;document.querySelectorAll('.cancel-knowledge').forEach(button=>button.onclick=()=>showKnowledgePanel(state.selectedSource?'knowledge-detail':'knowledge-empty'));$('manual-source-form').onsubmit=createManualKnowledge;$('file-source-form').onsubmit=createFileKnowledge;$('knowledge-file').onchange=event=>$('selected-file').textContent=event.target.files[0]?.name||'TXT, PDF ou DOCX · máximo de 10 MB';$('delete-source').onclick=deleteKnowledgeSource;$('ai-form').onsubmit=saveAIConfiguration;$('run-simulation').onclick=runAISimulation;$('refresh-suggestions').onclick=refreshKnowledgeSuggestions;$('whatsapp-form').onsubmit=createWhatsAppAccount;$('verify-whatsapp').onclick=verifyWhatsAppAccount;$('sync-templates').onclick=syncWhatsAppTemplates;
$('nav-settings').onclick=()=>showSection('settings');$('company-form').onsubmit=saveCompanyProfile;$('new-user').onclick=()=>{$('user-form').classList.remove('hidden');$('new-user-name').focus()};$('cancel-user').onclick=()=>{$('user-form').reset();$('user-form').classList.add('hidden')};$('user-form').onsubmit=createTeamMember;$('open-registration').onclick=()=>showAuthPanel('registration');$('registration-form').onsubmit=registerOrganization;$('forgot-password').onclick=()=>showAuthPanel('forgot');document.querySelectorAll('.back-to-login').forEach(button=>button.onclick=()=>showAuthPanel('login'));$('forgot-form').onsubmit=requestPasswordReset;$('reset-form').onsubmit=resetPassword;$('refresh-audit').onclick=refreshAuditLogs;
